```ts
import { GRAPH_TOOLS, handleToolCall, KNOWN_ACTORS, type ToolCallContext } from './causal-agent.js';

const VALID_ACTORS = new Set<string>(KNOWN_ACTORS);

// Inside runAgent, after destructuring req, before any work:
