```

Step 3 — replace `readBody` (lines 297-303) with a size-capped variant:

```ts
const MAX_BODY_BYTES = 1_000_000;
function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    let body = '';
    let size = 0;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        req.destroy();
        reject(new Error(`Request body exceeds ${MAX_BODY_BYTES} bytes`));
        return;
      }
      body += chunk.toString('utf8');
    });
    req.on('end', () => resolve(body));
    req.on('error', reject);
  });
}
```

Step 4 — in the `/run` POST handler, surface the `readBody` rejection as HTTP 413 (currently it lands in the generic 500 catch). Add explicit branch:

